SELECT e.id, e.space_id, e.edge_id, e.source_document_id, d.name AS source_document_name, e.quote, e.locator, e.extraction_method, e.created_at FROM evidences e INNER JOIN source_documents d ON d.id = e.source_document_id WHERE e.space_id = #{spaceId} AND e.edge_id IN
#{edgeId}
ORDER BY e.created_at ASC, e.id ASC
